    if (points.size() < 3) return result;

    // Create and initialize CGAL's Delaunay triangulation
    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_2<K> DT;
    typedef CGAL::Voronoi_diagram_2<DT, CGAL::Delaunay_triangulation_adaptation_traits_2<DT>, CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT>> VD;

    VD vd;
    for (const Point2d& p : points) {
        vd.insert(K::Point_2(p.x(), p.y()));
    }

    // Extract Voronoi cells
    for (VD::Vertex_iterator vit = vd.vertices_begin(); vit != vd.vertices_end(); ++vit) {
        VD::Halfedge_around_vertex_circulator ccw = (*vit)->incident_halfedges();
        VD::Halfedge_around_vertex_circulator done = ccw;
        std::vector<Point2d> cellVertices;
        if (ccw != 0) {
            VD::Halfedge_handle he = done;
            do {
                if (!he->is_unbounded()) {
                    cellVertices.push_back(Point2d(he->point().x(), he->point().y()));
                }
                ++ccw;
            } while (ccw != done);
        }
        result.push_back(cellVertices);
    }
    return result;"

